"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["96229"],{94233(e){e.exports=JSON.parse('{"id":"F318","slug":"futures-margin-account","name":"Futures Daily Settlement and Margin Account","subject":"Derivatives","section":"Derivatives","topic":"Futures and margining","level":"Intermediate","aliases":["marking to market","variation margin","initial margin","maintenance margin","margin call futures"],"formula":{"latex":"\\\\text{Daily gain}=N\\\\times M\\\\times(F_{t}-F_{t-1}),\\\\quad \\\\text{Balance}_{t}=\\\\text{Balance}_{t-1}+\\\\text{Daily gain}","also":[],"text":"Daily gain on a long position = Contracts x Multiplier x (Today\'s futures price - Yesterday\'s futures price); Margin balance = Previous balance + Daily gain"},"symbols":[{"symbol":"N","meaning":"Number of contracts held (long)","unit":"number"},{"symbol":"M","meaning":"Contract multiplier, the money value of one price point","unit":"money"},{"symbol":"F_t","meaning":"Settlement price of the futures on day t","unit":"money"},{"symbol":"Initial margin","meaning":"Deposit required per contract to open the position","unit":"money"},{"symbol":"Maintenance margin","meaning":"Level per contract below which a margin call is issued","unit":"money"}],"when_to_use":"Use it to follow a futures position through daily settlement. Gains and losses are paid each day, unlike a forward. When the balance falls below the maintenance level, the holder must deposit enough to return to the initial margin.","worked_example":{"problem":"You buy 10 index futures contracts with a multiplier of 50. The initial margin is 6,000 per contract and the maintenance margin is 4,500. Settlement prices on four days are 4,000, 3,980, 3,950 and 3,920. What happens to the account?","inputs":{"n":10,"m":50,"f":[4000,3980,3950,3920],"im":6000,"mm":4500},"steps":[{"label":"Daily gain = contracts x multiplier x price change","working":null,"value":"-10,000.00, -15,000.00, -15,000.00"},{"label":"Margin balance after each day (no top-ups)","working":null,"value":"50,000.00, 35,000.00, 20,000.00"},{"label":"Maintenance level for the whole position","working":"4500 x 10","value":"45,000.00"},{"label":"Lowest balance","working":"min([50000, 35000, 20000])","value":"20,000.00"},{"label":"Margin call to restore the initial margin (0 if none)","working":"max(6000 x 10-20000, 0) if 20000<45000 else 0","value":"40,000.00"}],"answer":"The daily gains are -10,000.00, -15,000.00, -15,000.00. The balance after each day is 50,000.00, 35,000.00, 20,000.00. The maintenance level is 45,000.00 and the lowest balance is 20,000.00, so a margin call arrives and 40,000.00 must be deposited to return to the initial margin."},"calculator":{"available":true,"inputs":[{"id":"n","label":"Contracts held (long)","unit":"number","type":"number","default":10,"hint":"","min":1},{"id":"m","label":"Contract multiplier","unit":"money","type":"number","default":50,"hint":""},{"id":"f","label":"Daily settlement prices, starting with the purchase price","unit":"money","type":"list","default":[4000,3980,3950,3920],"hint":""},{"id":"im","label":"Initial margin per contract","unit":"money","type":"number","default":6000,"hint":""},{"id":"mm","label":"Maintenance margin per contract","unit":"money","type":"number","default":4500,"hint":""}],"checks":[{"expr":"count(f)>=2 and im>=mm","message":"Enter at least two prices, and an initial margin at least as large as the maintenance margin."}],"steps":[{"id":"chg","label":"Daily gain = contracts x multiplier x price change","expr":"scale(minus(f[1:], f[:-1]), n*m)","format":"list2"},{"id":"bal","label":"Margin balance after each day (no top-ups)","expr":"minus(cumsum(chg), -im*n)","format":"list2"},{"id":"maint","label":"Maintenance level for the whole position","expr":"mm*n","format":"money"},{"id":"low","label":"Lowest balance","expr":"min(bal)","format":"money"},{"id":"call","label":"Margin call to restore the initial margin (0 if none)","expr":"max(im*n-low, 0) if low<maint else 0","format":"money"}],"results":["bal","call"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"maint":45000,"low":20000,"call":40000}},"finder":{"finds":"A futures margin account\'s balance and any margin call","needs":"Contracts, multiplier, settlement prices, margins"},"related":[{"slug":"forward-contract-value","name":"Forward Contract: Fair Price, Value and Payoff"},{"slug":"margin-call-price","name":"Margin Call Price"}],"related_ids":["F317","F265"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Daily\xa0gain</mtext><mo>=</mo><mi>N</mi><mo>\xd7</mo><mi>M</mi><mo>\xd7</mo><mo stretchy=\\"false\\">(</mo><msub><mi>F</mi><mi>t</mi></msub><mo>\u2212</mo><msub><mi>F</mi><mrow><mi>t</mi><mo>\u2212</mo><mn>1</mn></mrow></msub><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mtext>Balance</mtext><mi>t</mi></msub><mo>=</mo><msub><mtext>Balance</mtext><mrow><mi>t</mi><mo>\u2212</mo><mn>1</mn></mrow></msub><mo>+</mo><mtext>Daily\xa0gain</mtext></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Daily gain}=N\\\\times M\\\\times(F_{t}-F_{t-1}),\\\\quad \\\\text{Balance}_{t}=\\\\text{Balance}_{t-1}+\\\\text{Daily gain}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"fv-compounding-m","name":"Future Value with Compounding m Times a Year"},"next":{"slug":"forward-price-cost-of-carry","name":"Futures Price: Cost of Carry"},"lesson":null,"total":522}')}}]);